import{_ as e,c as i,o as l,ah as p,ao as a,ap as t}from"./chunks/framework.Dq2_gudl.js";const f=JSON.parse('{"title":"Pets in Heaven — 牠們、天堂與你的悲傷","description":"寫給失去毛小孩的你：從聖經看動物的永恆、神的看顧，以及如何在悲傷中被接住。四篇溫柔的讀物。","frontmatter":{"title":"Pets in Heaven — 牠們、天堂與你的悲傷","description":"寫給失去毛小孩的你：從聖經看動物的永恆、神的看顧，以及如何在悲傷中被接住。四篇溫柔的讀物。"},"headers":[],"relativePath":"pets-in-heaven/index.md","filePath":"pets-in-heaven/index.md"}'),n={name:"pets-in-heaven/index.md"};function o(c,s,r,d,h,v){return l(),i("div",null,[...s[0]||(s[0]=[p('<div class="pl-quote"><p>「牠走了以後，我最想知道的只有一件事：牠現在好不好？我們還會再見嗎？」</p><p class="pl-quote-soft">聖經沒有用一句話回答所有問題，但它給了我們足夠的光，讓我們在最黑的夜裡仍能看見盼望。</p></div><section class="pl-section"><h2>寫在開始之前</h2><p class="pl-lead">這裡不是要你「快點走出來」的地方。這四篇文章，是寫給還在想念牠的你。</p><p>失去一隻動物同伴，是很特别的悲傷。很多人會說「不過是一隻狗」「再養一隻就好了」——但你知道那不是真的。牠記得你回家的腳步聲，牠在你最低潮的那一年一直靠在你的腳邊，牠的離開，帶走的是每天早晨第一個迎接你的眼神。</p><p>聖經其實對動物說了很多話。神創造牠們、餵養牠們、與牠們立約、把它們放在祂將要更新的世界裡。這些經文不能證明「每一隻寵物都在天堂」——聖經沒有那樣應許——但它們讓我們看見一件溫柔的事實：<strong>在神的計畫裡，動物從不是可以被丟棄的配角。</strong></p><p>願你在這裡讀到的，不只是經文，而是那位連麻雀都記得的神，如何也記得你的牠。</p></section><section class="pl-section"><h2>四篇給你讀的文章</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/pets-in-heaven/will-i-see-my-pet-again">牠會在那裡嗎？</a></h3><p>聖經裡關於動物與天堂的盼望——受造之物一同等候得贖，新天新地裡仍有動物的身影。</p><p class="pl-quote-soft">羅馬書 8:19-22 · 以賽亞書 11:6-9 · 啟示錄 21:4-5</p></div><div class="pl-new-card"><h3><a href="/pets-in-heaven/not-one-sparrow-forgotten">連一隻麻雀，祂都記得</a></h3><p>牠那麼小，世界會記得牠嗎？耶穌說：一隻麻雀掉在地上，天父都知道。</p><p class="pl-quote-soft">馬太福音 10:29-31 · 詩篇 147:9 · 詩篇 36:6</p></div><div class="pl-new-card"><h3><a href="/pets-in-heaven/rainbow-bridge-covenant">彩虹橋的彼端</a></h3><p>「彩虹橋」很美的說法，而聖經裡真的有彩虹——那是神與<em>一切活物</em>所立的永遠的約。</p><p class="pl-quote-soft">創世記 9:9-13 · 以賽亞書 65:25 · 啟示錄 5:13</p></div><div class="pl-new-card"><h3><a href="/pets-in-heaven/permission-to-grieve">允許自己悲傷</a></h3><p>你的眼淚，神都收在瓶子裡。悲傷不是信心不足，而是愛還在繼續。</p><p class="pl-quote-soft">詩篇 56:8 · 詩篇 34:18 · 馬太福音 5:4</p></div></div></section><section class="pl-section"><h2>讀的時候，你可以這樣做</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>慢慢讀，不必一次讀完</h3><p>一次讀一段就夠了。如果某一節經文讓你突然哭出來，那就停下來——那不是軟弱，那是愛在流動。</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>把牠的名字放進經文裡</h3><p>讀到「神餵養走獸」時，試著在心裡換成牠的名字。經文不是只給人的，神也這樣看顧牠。</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>讀完後，對牠說一句話</h3><p>你不需要寫得漂亮。一句「我很想你」就足夠了。想寫得更多，PetLoss 裡的引導式日記願意陪你。</p></div></div></section><section class="pl-section"><h2>全部經文一覽</h2><p class="pl-lead">這四篇文章提到的每一處聖經經文，都集中在這裡，方便你反覆讀、慢慢查。</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/pets-in-heaven/will-i-see-my-pet-again">牠會在那裡嗎？</a></h3><ul class="pl-verse-list"><li>羅馬書 8:19-22</li><li>以賽亞書 11:6-9</li><li>啟示錄 21:4-5</li><li>詩篇 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/pets-in-heaven/not-one-sparrow-forgotten">連一隻麻雀，祂都記得</a></h3><ul class="pl-verse-list"><li>馬太福音 10:29-31</li><li>詩篇 147:9</li><li>詩篇 36:6</li><li>詩篇 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/pets-in-heaven/rainbow-bridge-covenant">彩虹橋的彼端</a></h3><ul class="pl-verse-list"><li>創世記 9:9-13</li><li>以賽亞書 65:25</li><li>啟示錄 5:13</li><li>詩篇 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/pets-in-heaven/permission-to-grieve">允許自己悲傷</a></h3><ul class="pl-verse-list"><li>詩篇 56:8</li><li>詩篇 34:18</li><li>詩篇 147:3</li><li>馬太福音 5:4</li><li>約翰福音 11:35</li><li>啟示錄 21:4</li></ul></div></div></section><div class="pl-cta"><h2>願你在這裡，被輕輕接住。</h2><p>如果你想找一個地方安放牠的照片、寫下沒來得及說的話，PetLoss 會安靜地陪著你——無需帳號、不上傳、完全離線。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下載</a><p class="pl-disclaimer">這些文章提供的是信仰反思與情感陪伴，不構成專業的醫療、心理或諮商建議。如果你長時間被悲傷壓得無法生活，請尋求持證專業人士或本地支持專線的協助。聖經引文採用英王欽定本（KJV）。</p></div><div class="pl-bible"><h3>讓聖經的話繼續陪你</h3><p>這四篇文章引用的經文都出自聖經。用《彩虹聖經》隨時閱讀神的話、設定每日經文小工具，在想念牠的日子裡仍有一盞燈。</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="Rainbow Bible 聖經小工具顯示 2 Timothy 2:13" loading="lazy"><figcaption>每日經文放在主畫面</figcaption></figure><figure><img src="'+t+'" alt="Rainbow Bible App 的「天堂裡的毛孩」主題，顯示 Matthew 10:29-31" loading="lazy"><figcaption>切換到「天堂裡的毛孩」主題讀經</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 取得《彩虹聖經》</a></div>',7)])])}const g=e(n,[["render",o]]);export{f as __pageData,g as default};
